function N($v){Need ($null -ne $v) 'Missing numeric field';if($v -is [ValueType]){$x=[double]$v}else{$x=0.;Need (![string]::IsNullOrWhiteSpace([string]$v) -and [double]::TryParse([string]$v,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$x)) 'Nonnumeric field'};Need (![double]::IsNaN($x) -and ![double]::IsInfinity($x)) 'Nonfinite numeric field';return $x}
function Count($v){Need (($v -is [int] -or $v -is [long]) -and $v -ge 0) 'Expected nonnegative JSON integer edge count';return $v}
