$code=$null;$invokeFailure=$null;$priorityDuring=$null;$started=[DateTime]::UtcNow.ToString('o');$prior=$ErrorActionPreference;$launcher=[Diagnostics.Process]::GetCurrentProcess();$oldPriority=$launcher.PriorityClass
Push-Location $working
try{$launcher.PriorityClass=[Diagnostics.ProcessPriorityClass]::Normal;$priorityDuring=[string]$launcher.PriorityClass;$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $h.program.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$invokeFailure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$prior;try{$launcher.PriorityClass=$oldPriority}catch{if(!$invokeFailure){$invokeFailure='Launcher priority restore failed: '+$_.Exception.Message}}}
